// AI output from previous node
const data = { ...$json };

// Validation report
const validation = {
  valid: true,
  errors: [],
  warnings: []
};

// ===============================
// Required Fields
// ===============================

const requiredFields = [
  "category",
  "subcategory",
  "priority",
  "urgency",
  "sentiment",
  "language",
  "confidence",
  "requires_human",
  "summary",
  "recommended_action",
  "reasoning"
];

for (const field of requiredFields) {
  if (!(field in data)) {
    validation.valid = false;
    validation.errors.push(`Missing field: ${field}`);
  }
}

// Stop immediately if required fields are missing
if (!validation.valid) {
  return [{
    json: {
      validation,
      ai_output: data
    }
  }];
}

// ===============================
// Allowed Values
// ===============================

const allowed = {

  category: [
    "Sales",
    "Support",
    "HR",
    "Finance",
    "Legal",
    "Marketing",
    "IT",
    "Operations",
    "Meeting",
    "Spam",
    "General",
    "Unknown"
  ],

  priority: [
    "Critical",
    "High",
    "Medium",
    "Low"
  ],

  urgency: [
    "Immediate",
    "Today",
    "This Week",
    "No Deadline"
  ],

  sentiment: [
    "Very Positive",
    "Positive",
    "Neutral",
    "Negative",
    "Very Negative"
  ],

  language: [
    "English",
    "Urdu",
    "Mixed",
    "Other"
  ]

};

// ===============================
// Category
// ===============================

if (!allowed.category.includes(data.category)) {
  validation.errors.push("Invalid category");
  data.category = "Unknown";
}

// ===============================
// Priority
// ===============================

if (!allowed.priority.includes(data.priority)) {
  validation.errors.push("Invalid priority");
  data.priority = "Medium";
}

// ===============================
// Urgency
// ===============================

if (!allowed.urgency.includes(data.urgency)) {
  validation.errors.push("Invalid urgency");
  data.urgency = "No Deadline";
}

// ===============================
// Sentiment
// ===============================

if (!allowed.sentiment.includes(data.sentiment)) {
  validation.errors.push("Invalid sentiment");
  data.sentiment = "Neutral";
}

// ===============================
// Language
// ===============================

if (!allowed.language.includes(data.language)) {
  validation.errors.push("Invalid language");
  data.language = "Other";
}

// ===============================
// Confidence
// ===============================

data.confidence = Number(data.confidence);

if (isNaN(data.confidence)) {
  validation.errors.push("Confidence is not numeric");
  data.confidence = 0;
}

data.confidence = Math.max(0, Math.min(100, data.confidence));

// ===============================
// Boolean Check
// ===============================

if (typeof data.requires_human !== "boolean") {
  validation.errors.push("requires_human is not boolean");
  data.requires_human = true;
}

// ===============================
// String Checks
// ===============================

const stringFields = [
  "subcategory",
  "summary",
  "recommended_action",
  "reasoning"
];

for (const field of stringFields) {

  if (typeof data[field] !== "string") {

    validation.errors.push(`${field} is not a string`);

    data[field] = "";
  }

}

// ===============================
// Word Limits
// ===============================

const summaryWords = data.summary.trim().split(/\s+/).filter(Boolean);

if (summaryWords.length > 30) {
  validation.warnings.push("Summary exceeds 30 words");
}

const reasoningWords = data.reasoning.trim().split(/\s+/).filter(Boolean);

if (reasoningWords.length > 40) {
  validation.warnings.push("Reasoning exceeds 40 words");
}

// ===============================
// Validation Status
// ===============================

if (validation.errors.length > 0) {
  validation.valid = false;
}

// ===============================
// Return
// ===============================

return [{
  json: {
    ...data,
    validation
  }
}];

