// ==========================================
// Enterprise JSON Parser
// Converts LLM text output into JSON safely
// ==========================================

const rawText = $json.text ?? "";

// Parser result metadata
const parser = {
    success: false,
    error: "",
    cleaned_text: "",
    parse_time: new Date().toISOString()
};

let cleanedText = rawText;

// ==========================================
// Remove Markdown Code Fences
// ==========================================

cleanedText = cleanedText
    .replace(/^\s*```json\s*/i, "")
    .replace(/^\s*```\s*/i, "")
    .replace(/\s*```\s*$/i, "")
    .trim();

parser.cleaned_text = cleanedText;

// ==========================================
// Empty Response Check
// ==========================================

if (cleanedText.length === 0) {

    parser.error = "LLM returned an empty response.";

    return [{
        json: {
            parser,
            parse_error: true,
            validation: {
                valid: false
            }
        }
    }];
}

// ==========================================
// JSON Parsing
// ==========================================

let parsed;

try {

    parsed = JSON.parse(cleanedText);

    parser.success = true;

} catch (err) {

    parser.error = err.message;

    return [{
        json: {
            parser,
            parse_error: true,
            validation: {
                valid: false
            },
            raw_output: cleanedText
        }
    }];
}

// ==========================================
// Ensure Parsed Object
// ==========================================

if (
    parsed === null ||
    Array.isArray(parsed) ||
    typeof parsed !== "object"
) {

    return [{
        json: {
            parser: {
                ...parser,
                success: false,
                error: "Parsed JSON is not a valid object."
            },
            parse_error: true,
            validation: {
                valid: false
            },
            raw_output: cleanedText
        }
    }];
}

// ==========================================
// Success
// ==========================================

return [{
    json: {
        ...parsed,
        parser,
        parse_error: false
    }
}];

