    ]

};

// =====================================================
// Helpers
// =====================================================

function deduct(points){
    validation.quality_score =
        Math.max(0, validation.quality_score - points);
}

// Normalize capitalization

function normalize(value){

    if(typeof value !== "string")
        return "";

    return value
        .trim()
        .toLowerCase()
        .replace(/\s+/g," ");
}

// Validate enum

function validateEnum(field, fallback){

    const allowed = enums[field];

    let value = data[field];

    if(typeof value !== "string"){

        validation.warnings.push(`${field} missing`);

        data[field] = fallback;

        validation.corrected_fields.push(field);

        deduct(5);

        return;
    }

    const normalized = normalize(value);

    const match = allowed.find(v =>
        normalize(v) === normalized
    );

    if(match){

        if(match !== value){

            validation.corrected_fields.push(field);

            deduct(1);

        }

        data[field] = match;

        return;
    }

    validation.warnings.push(`${field} invalid`);

    data[field] = fallback;

    validation.corrected_fields.push(field);

    deduct(5);

}

// Validate number

function validateNumber(field){

    let value = data[field];

    if(typeof value === "string"){

        value = parseInt(value);

    }

    if(isNaN(value)){

        validation.errors.push(`${field} invalid`);

        data[field] = 0;

        validation.valid = false;

        deduct(20);

        return;
    }

    value = Math.max(0,Math.min(100,value));

    data[field] = value;

}

// Validate text

function validateText(field,fallback,maxLength){

    let value = data[field];

    if(typeof value !== "string"){

        data[field]=fallback;

        validation.corrected_fields.push(field);

        deduct(5);

        return;
    }

    value = value.trim();

    if(value===""){

        value=fallback;

        validation.corrected_fields.push(field);

        deduct(5);

    }

    if(value.length>maxLength){

        value=value.substring(0,maxLength);

        validation.corrected_fields.push(field);

        deduct(2);

    }

    data[field]=value;

}

