// ============================================================
// SALES DECISION ENGINE V2.0 (CORE ENGINE)
// Part 1
// ============================================================

// ------------------------------------------------------------
// Read Input
// ------------------------------------------------------------

const data = { ...$json };

// ------------------------------------------------------------
// Decision Object
// ------------------------------------------------------------

const decision = {
    engine: "Sales Decision Engine",
    version: "2.0.0",
    created_at: new Date().toISOString(),

    ready_for_automation: true,
    save_to_crm: true,

    assigned_to: "Sales Executive",

    status: "New",

    priority_level: "Low",

    severity: "P4",

    notify_sales: false,

    create_followup: false,

    draft_reply: false,

    escalate: false,

    followup_due: "",

    reason: []
};

// ------------------------------------------------------------
// Helper Functions
// ------------------------------------------------------------

function addReason(text) {

    if (!decision.reason.includes(text))
        decision.reason.push(text);

}

function setPriority(level) {

    decision.priority_level = level;

    switch (level) {

        case "Critical":
            decision.severity = "P1";
            break;

        case "High":
            decision.severity = "P2";
            break;

        case "Medium":
            decision.severity = "P3";
            break;

        default:
            decision.severity = "P4";

    }

}

function assignSalesOwner() {

    if (
        data.lead_score >= 90 ||
        data.buying_intent === "Very High"
    ) {

        decision.assigned_to = "Senior Sales";
        addReason("Assigned to Senior Sales");

    }

    else {

        decision.assigned_to = "Sales Executive";
        addReason("Assigned to Sales Executive");

    }

}

function determineCRMStatus() {

    if (data.lead_score >= 90) {

        decision.status = "Qualified";

    }

    else if (data.lead_score >= 70) {

        decision.status = "New";

    }

    else if (data.lead_score >= 40) {

        decision.status = "Needs Qualification";

    }

    else {

        decision.status = "Nurture";

    }

    addReason(`CRM Status: ${decision.status}`);

}

function determinePriority() {

    if (data.lead_score >= 90) {

        setPriority("Critical");

    }

    else if (data.lead_score >= 75) {

        setPriority("High");

    }

    else if (data.lead_score >= 50) {

        setPriority("Medium");

    }

    else {

        setPriority("Low");

    }

    addReason(`Priority: ${decision.priority_level}`);

}

function validationGate() {

    if (!data.validation?.valid) {

        decision.ready_for_automation = false;

        decision.save_to_crm = false;

        decision.notify_sales = false;

        decision.create_followup = false;

        decision.draft_reply = false;

        decision.escalate = false;

        decision.assigned_to = "Human Review";

        decision.status = "Validation Failed";

        setPriority("Low");

        addReason("Validation failed");

        return false;

    }

    return true;

}

// ------------------------------------------------------------
// Execute Validation First
// ------------------------------------------------------------

if (!validationGate()) {

    return [{
        json: {
            ...data,
            decision
        }
    }];

}

// ------------------------------------------------------------
// Owner Assignment
// ------------------------------------------------------------

assignSalesOwner();

// ------------------------------------------------------------
// CRM Status
// ------------------------------------------------------------

determineCRMStatus();

// ------------------------------------------------------------
// Priority
// ------------------------------------------------------------

determinePriority();

// ------------------------------------------------------------
// Notification Rules
// ------------------------------------------------------------

if (

    data.lead_temperature === "Hot"

    ||

    data.buying_intent === "Very High"

    ||

    data.response_priority === "Immediately"

    ||

    data.lead_score >= 85

) {

    decision.notify_sales = true;

    addReason("Sales notification required");

}

// ------------------------------------------------------------
// Draft Reply Rules
// ------------------------------------------------------------

if (

    data.validation.valid

    &&

    data.lead_score >= 70

) {

    decision.draft_reply = true;

    addReason("AI Draft Reply");

}

// ------------------------------------------------------------
// Follow-up Rules
// ------------------------------------------------------------

if (data.lead_score >= 60) {

    decision.create_followup = true;

    addReason("Follow-up required");

}

// ------------------------------------------------------------
// Escalation Rules
// ------------------------------------------------------------

if (

    (
        data.estimated_budget === "High" &&
        data.probability_to_close >= 80
    )

    ||

    data.lead_score >= 95

    ||

    data.timeline === "Immediate"

) {

    decision.escalate = true;

    addReason("Escalation required");

}

// ------------------------------------------------------------
// Follow-up Scheduling
// ------------------------------------------------------------

if (decision.create_followup) {

    const followup = new Date();

    switch (data.response_priority) {

        case "Immediately":

            followup.setHours(
                followup.getHours() + 1
            );

            break;

        case "Within 1 Hour":

            followup.setHours(
                followup.getHours() + 1
            );

            break;

        case "Today":

            followup.setHours(
                followup.getHours() + 8
            );

            break;

        case "Tomorrow":

            followup.setDate(
                followup.getDate() + 1
            );

            break;

        default:

            followup.setDate(
                followup.getDate() + 7
            );

    }

    decision.followup_due = followup.toISOString();

}

// ------------------------------------------------------------
// Automation Readiness
// ------------------------------------------------------------

decision.ready_for_automation = (

    decision.save_to_crm

    &&

    data.validation.valid

);

// ------------------------------------------------------------
// Decision Summary
// ------------------------------------------------------------

addReason(`Lead Score: ${data.lead_score}`);

addReason(`Lead Temperature: ${data.lead_temperature}`);

addReason(`Buying Intent: ${data.buying_intent}`);

addReason(`Estimated Budget: ${data.estimated_budget}`);

addReason(`Timeline: ${data.timeline}`);

addReason(
    `Probability to Close: ${data.probability_to_close}%`
);

addReason(
    `Assigned To: ${decision.assigned_to}`
);

// ------------------------------------------------------------
// Recommendation
// ------------------------------------------------------------

decision.recommended_workflow = {

    create_airtable_record:
        decision.save_to_crm,

    notify_sales_team:
        decision.notify_sales,

    create_followup_task:
        decision.create_followup,

    create_email_draft:
        decision.draft_reply,

    escalate:
        decision.escalate

};

// ------------------------------------------------------------
// Audit Information
// ------------------------------------------------------------

decision.audit = {

    engine: decision.engine,

    version: decision.version,

    processed_at: decision.created_at,

    automation_ready:
        decision.ready_for_automation

};

// ------------------------------------------------------------
// Output
// ------------------------------------------------------------

return [

{

    json: {

        ...data,

        decision

    }

}

